import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import {setLogger} from '../../shared/logger.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {ChatSession} from '../../types/session.js';
import type {ConversationCursor, OutgoingMessage} from '../../types/messages.js';
import {StoreCannotList, type SessionStore, type SessionSummary} from '../../types/sessionStore.js';

function testSocket(sent: OutgoingMessage[]): WebSocket {
  return {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
}

function enabledHandler(store: SessionStore) {
  return createMessageHandler({} as ChatOrchestrator, store, {history: {enabled: true}});
}

async function expectUnsupportedHistory(
  handler: ReturnType<typeof createMessageHandler>,
  sent: OutgoingMessage[]
): Promise<void> {
  await handler(testSocket(sent), {sessionId: 'active', userId: 'u1', entries: []}, {type: 'list_conversations'});
  expect(sent).toEqual([{type: 'error', code: 'UNSUPPORTED', message: 'Conversation history is not available'}]);
}

describe('conversation list message handling', () => {
  it('lists the authenticated user conversations and serializes their dates', async () => {
    const sent: OutgoingMessage[] = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const listFor = jest.fn(() => summaries);
    const store = {listFor} as unknown as SessionStore;
    const handler = createMessageHandler({} as ChatOrchestrator, store, {history: {enabled: true}});
    const ws = testSocket(sent);
    const session: ChatSession = {sessionId: 'active', userId: 'u1', entries: []};
    const before: ConversationCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    await handler(ws, session, {type: 'list_conversations', limit: 10, before, userId: 'u2'});

    expect({called: listFor.mock.calls, sent}).toEqual({
      called: [['u1', {limit: 10, before}]],
      sent: [
        {
          type: 'conversation_list',
          conversations: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  it('takes the conversation owner from the authenticated socket', async () => {
    const sent: OutgoingMessage[] = [];
    const listFor = jest.fn(() => []);
    const handler = enabledHandler({listFor} as unknown as SessionStore);
    const ws = {...testSocket(sent), userId: 'socket-user'} as WebSocket & {userId: string};
    const session: ChatSession = {sessionId: 'active', userId: 'session-user', entries: []};

    await handler(ws, session, {type: 'list_conversations', userId: 'other-user'});

    expect(listFor).toHaveBeenCalledWith('socket-user', {limit: undefined, before: undefined});
  });

  it('refuses conversation history when the feature is disabled', async () => {
    const sent: OutgoingMessage[] = [];
    const listFor = jest.fn(() => []);
    const store = {listFor} as unknown as SessionStore;
    const handler = createMessageHandler({} as ChatOrchestrator, store);
    const ws = testSocket(sent);
    const session: ChatSession = {sessionId: 'active', userId: 'u1', entries: []};

    await handler(ws, session, {type: 'list_conversations'});

    expect({sent, calls: listFor.mock.calls}).toEqual({
      sent: [{type: 'error', code: 'UNSUPPORTED', message: 'Conversation history is not available'}],
      calls: [],
    });
  });

  it('refuses history when the enabled store cannot list conversations', async () => {
    const sent: OutgoingMessage[] = [];
    const handler = createMessageHandler({} as ChatOrchestrator, {} as SessionStore, {history: {enabled: true}});
    await expectUnsupportedHistory(handler, sent);
  });

  it('treats StoreCannotList as unsupported history', async () => {
    const sent: OutgoingMessage[] = [];
    const listFor = jest.fn(async () => {
      throw new StoreCannotList();
    });
    const handler = enabledHandler({listFor} as unknown as SessionStore);
    await expectUnsupportedHistory(handler, sent);
  });

  it('answers a failing store without logging its detail', async () => {
    const sent: OutgoingMessage[] = [];
    const secret = 'mongodb://user:password@example.test';
    const listFor = jest.fn(async () => {
      throw new Error(secret);
    });
    const store = {listFor} as unknown as SessionStore;
    const error = jest.fn();
    setLogger({debug: jest.fn(), info: jest.fn(), warn: jest.fn(), error});

    try {
      const handler = createMessageHandler({} as ChatOrchestrator, store, {history: {enabled: true}});
      const ws = testSocket(sent);
      const session: ChatSession = {sessionId: 'active', userId: 'u1', entries: []};

      await handler(ws, session, {type: 'list_conversations'});

      expect({sent, errorCalls: error.mock.calls}).toEqual({
        sent: [{type: 'error', code: 'SERVER_ERROR', message: 'Failed to list conversations'}],
        errorCalls: [['ws', 'conversation list failed', {sessionId: 'active', error: 'Error'}]],
      });
    } finally {
      setLogger();
    }
  });
});
